CREATE OR REPLACE FUNCTION public.sync_survey_answers_from_proof()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (NEW.survey_answers IS NULL OR NEW.survey_answers = '{}'::jsonb)
     AND NEW.proof IS NOT NULL THEN
    BEGIN
      IF (NEW.proof::jsonb ? 'answers') THEN
        NEW.survey_answers := NEW.proof::jsonb->'answers';
      END IF;
    EXCEPTION WHEN others THEN
      NULL;
    END;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_profile_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.id <> old.id or new.points <> old.points or new.role <> old.role or new.created_at <> old.created_at then
    raise exception 'Protected profile fields cannot be changed directly';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.add_points_for_approved_submission(p_submission_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  s public.task_submissions%rowtype;
  t_points integer;
  existing_count integer;
begin
  if not private.is_admin() then
    raise exception 'Admin authorization required';
  end if;

  select * into s
  from public.task_submissions
  where id = p_submission_id
  for update;

  if not found then raise exception 'Submission not found'; end if;
  if s.status <> 'pending' then raise exception 'Submission is not pending'; end if;

  select points into t_points
  from public.tasks
  where id = s.task_id
  for share;

  if t_points is null then raise exception 'Task not found'; end if;

  select count(*) into existing_count
  from public.points_ledger
  where submission_id = s.id;

  if existing_count > 0 then raise exception 'Points already awarded for this submission'; end if;

  update public.task_submissions
  set status = 'approved', reviewed_at = pg_catalog.now()
  where id = s.id;

  update public.profiles
  set points = points + t_points
  where id = s.user_id;

  if not found then raise exception 'User profile not found'; end if;

  insert into public.points_ledger(user_id, submission_id, amount, reason)
  values (s.user_id, s.id, t_points, 'Task submission approved');
end;
$function$

CREATE OR REPLACE FUNCTION private.process_redemption_request(p_request_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  r public.redemption_requests%rowtype;
  current_points integer;
begin
  if not private.is_admin() then
    raise exception 'Admin authorization required';
  end if;

  select * into r
  from public.redemption_requests
  where id = p_request_id
  for update;

  if not found then raise exception 'Reward request not found'; end if;
  if r.status <> 'pending' then raise exception 'Reward request is not pending'; end if;

  select points into current_points
  from public.profiles
  where id = r.user_id
  for update;

  if coalesce(current_points,0) < r.points_requested then
    raise exception 'Insufficient user balance';
  end if;

  update public.profiles
  set points = points - r.points_requested
  where id = r.user_id;

  insert into public.points_ledger(user_id, submission_id, amount, reason)
  values (r.user_id, null, -r.points_requested, 'Withdrawal approved');

  update public.redemption_requests
  set status = 'approved', reviewed_at = pg_catalog.now()
  where id = r.id;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_notification_user_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF private.is_admin() THEN
    RETURN NEW;
  END IF;

  IF (SELECT auth.uid()) IS NULL OR OLD.user_id IS DISTINCT FROM (SELECT auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized to update this notification';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.title IS DISTINCT FROM OLD.title
     OR NEW.message IS DISTINCT FROM OLD.message
     OR NEW.type IS DISTINCT FROM OLD.type
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Only the read status can be changed';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.protect_task_submission_user_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF private.is_admin() THEN
    RETURN NEW;
  END IF;

  IF (SELECT auth.uid()) IS NULL OR OLD.user_id IS DISTINCT FROM (SELECT auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized to update this submission';
  END IF;

  IF OLD.status IS DISTINCT FROM 'pending' OR NEW.status IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'Users may only edit pending submissions';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.task_id IS DISTINCT FROM OLD.task_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.reviewer_note IS DISTINCT FROM OLD.reviewer_note
     OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
     OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at THEN
    RAISE EXCEPTION 'Protected submission fields cannot be changed';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.create_redemption_request(p_points integer, p_reward_type text DEFAULT 'manual_reward'::text, p_user_note text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  new_id bigint;
  current_points integer;
  pending_points integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_points IS NULL OR p_points <= 0 THEN
    RAISE EXCEPTION 'Points requested must be greater than zero';
  END IF;

  -- Lock this user's profile row for the duration of the request.
  SELECT points
  INTO current_points
  FROM public.profiles
  WHERE id = auth.uid()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;

  SELECT COALESCE(SUM(points_requested), 0)::integer
  INTO pending_points
  FROM public.redemption_requests
  WHERE user_id = auth.uid()
    AND status = 'pending';

  IF current_points - pending_points < p_points THEN
    RAISE EXCEPTION 'Insufficient available reward points';
  END IF;

  INSERT INTO public.redemption_requests(
    user_id, points_requested, reward_type, user_note
  )
  VALUES (
    auth.uid(),
    p_points,
    COALESCE(NULLIF(BTRIM(p_reward_type), ''), 'manual_reward'),
    NULLIF(BTRIM(p_user_note), '')
  )
  RETURNING id INTO new_id;

  RETURN new_id;
END;
$function$
